// Starlight route middleware. The pages generated by starlight-openapi have
// no description: give each one, so that search engines and link previews
// get a summary in French like every other page.
import { defineRouteMiddleware } from '@astrojs/starlight/route-data';
import { SITE_NAME } from './lib/meta.ts';
import { REFERENCE_PATH } from './lib/site.ts';

const TAGS_PATH = `${REFERENCE_PATH}operations/tags/`;

/** The description of a generated reference page, from its path and title. */
function referenceDescription(pathname: string, title: string): string {
  const api = `l'API ${SITE_NAME}`;
  let subject: string;
  if (pathname === REFERENCE_PATH) subject = `Référence de ${api}`;
  else if (pathname.startsWith(TAGS_PATH)) {
    const tag = decodeURIComponent(pathname.slice(TAGS_PATH.length).replace(/\/$/, ''));
    subject = `Référence des opérations « ${tag} » de ${api}`;
  }
  // An operation page is titled with the operation's summary.
  else subject = `${title} : référence de ${api}`;
  return `${subject}, générée depuis son contrat OpenAPI.`;
}

export const onRequest = defineRouteMiddleware((context) => {
  const route = context.locals.starlightRoute;
  if (!context.url.pathname.startsWith(REFERENCE_PATH)) return;
  if (route.head.some((tag) => tag.tag === 'meta' && tag.attrs?.name === 'description')) return;

  const content = referenceDescription(context.url.pathname, route.entry.data.title);
  route.head.push(
    { tag: 'meta', attrs: { name: 'description', content } },
    { tag: 'meta', attrs: { property: 'og:description', content } },
  );
});
